  "왜": "일이 먼저 바뀌었다고 하셨죠. 만난 해에 나는 이 사람한테 짝이 아닌 자리로 들어왔어요. 요 몇 해 온 운은 여자·돈 쪽인데, 이 사람은 그걸 먼저 일에 썼어요. 사람보다 형편이 먼저 서야 한다고 믿는 쪽이에요. 그래서 지금은 나를 결혼 상대로 옮겨 놓기 전 단계예요. 옮기지 않는다는 뜻은 아니에요. 오늘은 이 사람 일 얘기를 진지하게 들어 주세요. 형편을 같이 봐 주는 사람이 그다음 자리로 옮겨 가요."
