  "왜": "먼저 다가온다고 하셨죠. 밥값을 먼저 내고 주말을 비워 두고 만나자는 말을 먼저 꺼내는 게 다 그 표시예요. 원래 좋아하면 온 동네가 아는 사람인데, 요 몇 해 여자·돈의 운까지 들어와 있어서 평소보다 좀 더 빨리, 좀 더 크게 움직여요. 내가 본 것과 사주가 같은 말을 하는 거예요. 이 사람한테 연애가 처음은 아니라서 서두르지 않고 편하게 올 뿐이지 마음이 작은 게 아니에요. 운이 가도 마음이 사라지진 않고 평소 크기로 돌아가요. 오늘은 재지 말고 오는 대로 받으세요."
