  "왜": "말수가 늘었다고 하셨죠. 이 사람 운은 자리·일의 운이라, 맡은 일이 먼저 자리를 잡았을 거예요. 맡은 일이 생기면 사람은 말이 늘거든요. 친구들 사이에서도 듣기만 하던 사람이라 말이 늘었다는 건 이 사람 안에서 뭔가 단단해졌다는 뜻이에요. 말이 늘면 그 다음에 오는 게 여자고, 그 여자가 나일지는 지금 누가 그 말을 들어 주느냐로 정해져요. 이 운이 가면 말은 줄고 친구들이 다시 돌아오니, 말이 늘어 있는 동안 술 약속보다 내 약속이 먼저 잡히게 해 두세요. 오늘은 회사 얘기가 나오면 지루해하지 말고 하나 더 물어봐 주세요."
