  "왜": "승진이나 이직이 먼저였다고 하셨죠. 요 몇 해 자리·일의 운이 들어왔고, 사주도 같은 말을 해요. 마음을 안에 두고 늘 친구들이나 형들 사이에 묻혀 살던 사람이라 그 무리에서 빠져나오려면 자기 일이 먼저 생겨야 했는데, 지금 그게 됐어요. 그래서 요즘 술 약속이 줄고 혼자 있는 시간이 늘었을 거예요. 그 빈 시간에 들어오는 사람이 이 사람 여자가 돼요. 이 운이 가면 친구들이 다시 돌아오고 빈 시간도 닫히니, 그 전에 주말이면 나를 보는 게 당연해지게 해 두세요. 오늘은 주말에 뭐 하는지 물어보고 그 빈 시간에 먼저 들어가세요."
