  "왜": "카톡이 먼저 길어졌다고 하셨죠. 요 몇 해 이 사람 운은 말이 트일 운이 아니에요. 그런데도 말수 적고 속으로 삭이는 사람이 나한테 먼저 길게 보내고 시답잖은 얘기까지 하게 됐다면, 그건 운이 시킨 게 아니라 이 사람이 애쓰는 거예요. 애써서 나온 말은 진심인데 오래 못 가서, 이어 가는 힘은 나한테서 나와야 해요. 며칠 답이 없거나 다시 짧아져도 식은 게 아니라 숨 고르는 거예요. 오늘은 짧아진 날에 먼저 길게 보내 주세요."
