  "왜": "먼저 다가오고 씀씀이가 달라졌다고 하셨죠. 이 사람은 원래 먼저 내는 손을 가진 사람이에요. 요 몇 해 말·표현의 운이 들어와서 그 손에 이유가 붙었어요. 전에는 습관으로 샀다면 요즘은 「이거 좋아할 것 같아서」로 사요. 사 주는 게 곧 이 사람 말이에요. 운이 가면 그 말은 줄어도 사는 손은 원래 것이라 남아요. 오늘은 이 사람이 산 것 중 하나를 골라 왜 이걸 골랐냐고 물어보세요. 그 대답이 고백이에요."
