  "왜": "달라진 게 없다고 하셨죠. 이 사람은 원래 먼저 내는 사람이라 사 주는 것 자체는 새로울 게 없어요. 요 몇 해 말·표현의 운이 와 있어서 지금은 말이 먼저 늘어날 때예요. 사는 건 그대로인데 사면서 하는 말이 달라지면 그게 시작이에요. 곧 보여요. 「이거 좋아할 것 같아서」가 붙는지 보세요. 운이 가면 그 말은 줄어도 손은 남아요. 오늘은 이 사람이 산 것에 「어떻게 알았어요」라고 해 보세요. 이 사람 말이 거기서 나와요."
