  "왜": "일이 바뀌었다고 하셨죠. 사주도 같은 말을 해요. 요 몇 해 자리·일의 운이 들어와서 책임이 생겼고, 이 사람은 원래 먼저 사는 손이라 그 손이 회사에서도 나가요. 후배 밥 사고 팀 커피 사고. 그래서 요즘 나한테 덜 사는 것 같으면 손이 줄어든 게 아니라 나가는 데가 늘어난 거예요. 일이 자리 잡으면 다시 이쪽이 커져요. 운이 가면 회사 쪽 손은 줄고 원래 손이 남아요. 오늘은 「요즘 회사에서 많이 사죠?」라고 물어보세요. 이 사람이 웃으면 맞는 거예요."
