  "왜": "일이 바뀌었다고 하셨죠. 요 몇 해 이 사람한테는 일이 서는 운이 안 와 있어서, 이번 변화는 운이 아니라 이 사람이 스스로 한 거예요. 원래 손이 없는 사람이 자기 일까지 바꿨으니 지금은 사 줄 여유가 없어요. 마음이 없는 게 아니라 순번이 밀린 거예요. 운이 안 받쳐 주는 변화라 흔들릴 수 있고, 그때 옆에 있어 준 사람이 이 사람한테 남아요. 오늘은 새 일이 어떤지 묻고 이번엔 사세요. 이 사람이 오래 기억해요."
