  "왜": "말이 늘었다고 하셨죠. 사주도 같은 말을 해요. 이 사람은 셋이 모이면 듣는 하나였고, 남한테 뭘 사 준 적도 없는 사람이에요. 요 몇 해 말·표현의 운이 들어와 입이 열렸고, 입이 열리니 내가 보이기 시작한 거예요. 서툰 말이라 어색해도 전부 진심이에요. 사 주는 건 그 다음 순서라 아직이에요. 이 사람한테는 말이 곧 사 주는 거예요. 운이 지나가면 말수가 줄 수 있으니 그 안에 만나서 이야기하는 습관을 굳혀 두세요. 오늘은 이 사람 말을 끊지 말고 끝까지 들어 주세요."
