  "왜": "일이 바뀌었다고 하셨죠. 만난 해에 인연의 운이 왔으니 자리는 있어요. 다만 요 몇 해는 일이 서는 운이 없어서, 이번 변화는 이 사람이 스스로 한 거예요. 운이 안 받쳐 주는 변화라 흔들릴 수 있고, 그때 이 사람은 사람보다 일을 먼저 붙잡아요. 그 시기를 같이 넘기면 그 자리가 제일 단단해져요. 오늘은 잘하고 있다고 한마디만 해 주세요."
