  "왜": "일이 바뀌었다고 하셨죠. 사주도 같은 말을 해요. 요 몇 해 자리·일의 운이라 자리가 서고 있고, 자리가 서면 이 사람은 체면으로라도 쓰기 시작해요. 그게 원래 손이 늦은 이 사람의 지갑이 처음 열리는 길이에요. 그러니 축하가 곧 기회예요. 「승진했으니 한턱 내야죠」가 이 사람한테는 부탁이 아니라 명분이에요. 운이 가면 도로 늦어져요. 오늘 축하하면서 한 번 말해 보세요."
