  "왜": "먼저 다가오고 씀씀이가 달라졌다고 하셨죠. 요 몇 해 이 사람한테는 돈도 말도 일도 특별한 운이 없어요. 원래 손이 늦은 사람이 운 없이 쓴다면 무리해서 쓰는 거예요. 여기서 크게 말하면 이 사람이 금방 비고 관계가 끊겨요. 작게 말하고 다음 차례를 내가 가져가면 이 사람이 계속 올 수 있어요. 오늘은 작은 것 하나를 말하고 「다음엔 제가요」를 붙이세요."
