  "왜": "말이 늘었다고 하셨죠. 요 몇 해 이 사람한테는 말이 느는 운이 없는데도 늘었다면 애써서 나온 말이에요. 원래 손이 늦고 운도 손을 안 키우니 지갑은 계속 안 열려요. 여기서 물건을 말하면 이 사람은 못 해 주고 미안해하다 멀어져요. 대신 「이 얘기 계속 해 줘요」처럼 이 사람이 줄 수 있는 걸 말하면 이 관계가 이어져요. 오늘은 그 말에 길게 답하고 더 듣고 싶다고 하세요."
