  "왜": "일이 먼저 바뀌었다고 하셨죠. 요 몇 해 말·표현의 운이 들어와서 말이 늘었고 그 말로 새 일이 생긴 거예요. 원래 손이 늦은 사람인데 지금은 말까지 회사로 가서 이쪽이 두 배로 비어 보여요. 밀린 게 아니라 순서예요. 새 일이 돈이 되면 이 사람은 바로 써요. 오늘은 일 얘기를 들어 주고 「잘되면 밥 사요」라고 미리 말해 두세요."
