  "왜": "말이 늘었다고 하셨죠. 요 몇 해 자리·일의 운으로 일이 서는 중이고, 일이 서면 사람은 말이 늘고 어깨가 펴져요. 원래 감추지 못하는 사람이라 그게 다 나와요. 요즘 목소리가 커졌거나 자기 얘기가 늘었다면 그거예요. 잘난 척이 아니라 처음 서 보는 거예요. 이 시기에 알아주는 사람이 오래 남아요. 오늘은 이 사람 일이 잘되면 제일 먼저 축하해 주세요."
