  "왜": "일이 바뀌었다고 하셨죠. 사주도 같은 말을 해요. 요 몇 해 자리·일의 운으로 책임이 생기면서 늘 몰려다니던 친구들과 멀어지는 중이에요. 원래 시끌시끌하던 사람이 요즘 혼자 있고 연락도 줄었다면 그게 이유예요. 나한테 관심이 없어진 게 아니라 세상 전부에서 사람이 줄고 있는 거예요. 그 빈자리에 들어가는 사람이 남아요. 오늘은 이 사람이 새로 맡은 일을 아는 척해 주세요."
