  "왜": "달라진 게 없다고 하셨죠. 요 몇 해 이 사람을 바꾸는 운도 없어서 지금 보이는 게 전부예요. 말은 늘 다정하고 실제로 한 건 없죠. 좋은 점은 곁이 편하고 상처 주지 않는다는 것이고, 걸리는 점은 이 관계가 여기서 더 안 간다는 거예요. 그러니 물음을 바꾸셔야 해요. 좋은 사람인가가 아니라 여기까지로 괜찮은가예요."
