  "왜": "달라진 게 없다고 하셨죠. 요 몇 해 이 사람을 바꾸는 운도 없어서 원래 모습 그대로예요. 그리고 원래 이 사람은 한번 정하면 그쪽만 보고 갈아타는 데 서툰 사람이에요. 그러니 다른 사람 걱정은 안 하셔도 돼요. 대신 물을 건 이거예요. 지금 그 한 곳이 나인가. 오늘은 이 사람이 제일 시간을 많이 쓰는 데가 어딘지 보세요."
